contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public payable {
        require(deadline >= block.timestamp);

        bytes32 domainSeparator = c.DOMAIN_SEPARATOR(); if (__ESBMC_reverted()) return;
        bytes32 PERMIT_TYPEHASH = c.PERMIT_TYPEHASH(); if (__ESBMC_reverted()) return;
        uint256 nonceBefore = c.nonces(owner); if (__ESBMC_reverted()) return;

        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01",
                domainSeparator,
                keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonceBefore, deadline))
            )
        );

        address recovered = ecrecover(digest, v, r, s);
        require(recovered != owner);

        bool reverted;
        c.permit(owner, spender, value, deadline, v, r, s); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && c.allowance(owner, spender) == 0 && c.nonces(owner) == nonceBefore);
    }

    receive() external payable {}
}

